package com.aac.ieojwo.location.domain;
import com.aac.ieojwo.common.domain.BaseTimeEntity;import com.aac.ieojwo.device.domain.AacDevice;import com.aac.ieojwo.user.domain.AacUser;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="location_samples",indexes=@Index(name="idx_location_user_time",columnList="aac_user_id,recorded_at"))public class LocationSample extends BaseTimeEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="aac_user_id",nullable=false)private AacUser user;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="device_id",nullable=false)private AacDevice device;@Column(nullable=false)private double latitude;@Column(nullable=false)private double longitude;private Double accuracyMeters;@Column(nullable=false)private Instant recordedAt;protected LocationSample(){}public static LocationSample create(AacDevice d,double lat,double lon,Double accuracy,Instant at){LocationSample s=new LocationSample();s.user=d.getUser();s.device=d;s.latitude=lat;s.longitude=lon;s.accuracyMeters=accuracy;s.recordedAt=at==null?Instant.now():at;return s;}public Long getId(){return id;}public double getLatitude(){return latitude;}public double getLongitude(){return longitude;}public Double getAccuracyMeters(){return accuracyMeters;}public Instant getRecordedAt(){return recordedAt;}public AacUser getUser(){return user;}}
